mapper.select:
SELECT request_id, match_id, first_actor, second_actor, activity_id, phase, team_id, blocker,
       dispatched, created_at, updated_at
FROM w16_handoff_request WHERE match_id=#{matchId}

mapper.update:
UPDATE w16_handoff_request
SET phase=#{phase}, team_id=#{teamId,jdbcType=BIGINT}, blocker=#{blocker,jdbcType=VARCHAR},
    dispatched=#{dispatchedBit}, updated_at=#{updatedAt}
WHERE request_id=#{requestId} AND match_id=#{matchId}
  AND first_actor=#{firstActor} AND second_actor=#{secondActor} AND activity_id=#{activityId}
